type NameCheck =
  | { readonly accepted: true; readonly names: readonly string[] }
  | { readonly accepted: false; readonly message: string };

export function normalizePlayerName(value: string): string {
  return value.trim().replace(/\s+/gu, ' ').normalize('NFC');
}

export function checkPlayerNames(values: readonly string[], count: 4 | 8): NameCheck {
  if (values.length < count) return { accepted: false, message: 'Use 2 to 20 characters.' };
  const names = values.slice(0, count).map(normalizePlayerName);
  if (
    names.some((name) => {
      const length = Array.from(name).length;
      return length < 2 || length > 20;
    })
  )
    return { accepted: false, message: 'Use 2 to 20 characters.' };
  if (new Set(names.map((name) => name.toLowerCase())).size !== count)
    return { accepted: false, message: 'Each name must be different.' };
  return { accepted: true, names };
}
import { hasExactKeys, isJsonObject, parseJson } from '../saved-format.ts';
import { decodeTournamentRecord } from './validate.ts';
import type { TournamentReadResult } from './validate.ts';
import type { Tournament } from './model.ts';

const TOURNAMENTS_KEY = 'np3:tournaments';
const TOURNAMENTS_VERSION = 3;
const TOURNAMENTS_LIMIT = 10;

interface TournamentStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

interface TournamentHistoryRead {
  readonly available: boolean;
  readonly tournaments: readonly Tournament[];
}

export function prependFinishedTournament(
  tournament: Tournament,
  history: readonly Tournament[],
): readonly Tournament[] {
  return [tournament, ...history.filter((item) => item.id !== tournament.id)].slice(
    0,
    TOURNAMENTS_LIMIT,
  );
}

export function browserTournamentStore(): TournamentStore | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

export function readTournamentHistory(store: TournamentStore | null): TournamentHistoryRead {
  if (!store) return { available: false, tournaments: [] };
  let text: string | null;
  try {
    text = store.getItem(TOURNAMENTS_KEY);
  } catch {
    return { available: false, tournaments: [] };
  }
  if (!text) return { available: true, tournaments: [] };
  const value = parseJson(text);
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['items', 'v']) ||
    value.v !== TOURNAMENTS_VERSION ||
    !Array.isArray(value.items) ||
    value.items.length > TOURNAMENTS_LIMIT
  )
    return { available: true, tournaments: [] };
  const tournaments: Tournament[] = [];
  for (const item of value.items) {
    const result: TournamentReadResult = decodeTournamentRecord(item);
    if (!result.tournament || result.tournament.status !== 'finished')
      return { available: true, tournaments: [] };
    tournaments.push(result.tournament);
  }
  return { available: true, tournaments };
}

export function writeTournamentHistory(
  store: TournamentStore | null,
  tournaments: readonly Tournament[],
): boolean {
  if (!store) return false;
  try {
    store.setItem(
      TOURNAMENTS_KEY,
      JSON.stringify({ items: tournaments.slice(0, TOURNAMENTS_LIMIT), v: TOURNAMENTS_VERSION }),
    );
    return true;
  } catch {
    return false;
  }
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { checkPlayerNames } from './names.ts';

interface TournamentSetupProps {
  start(names: readonly string[], count: 4 | 8): void;
  leave(): void;
  report(message: string): void;
}

export function TournamentSetup({ start, leave, report }: TournamentSetupProps) {
  const [count, setCount] = useState<4 | 8>(4);
  const [drafts, setDrafts] = useState(() => Array.from({ length: 8 }, () => ''));
  const [error, setError] = useState('');

  function submit(event: FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    const checked = checkPlayerNames(drafts, count);
    if (!checked.accepted) {
      setError(checked.message);
      report(checked.message);
      return;
    }
    setError('');
    start(checked.names, count);
  }

  return (
    <section className="tournament-setup" aria-labelledby="tournament-setup-title">
      <h3 id="tournament-setup-title">Set up a tournament</h3>
      <form onSubmit={submit}>
        <div className="tournament-count">
          <label htmlFor="tournament-player-count">Players</label>
          <select
            id="tournament-player-count"
            className="control"
            value={count}
            onChange={(event) => setCount(event.currentTarget.value === '8' ? 8 : 4)}
          >
            <option value={4}>4</option>
            <option value={8}>8</option>
          </select>
        </div>
        <div className="tournament-name-grid">
          {drafts.slice(0, count).map((name, index) => {
            const id = `tournament-player-${index + 1}`;
            return (
              <div className="tournament-name-field" key={id}>
                <label htmlFor={id}>Player {index + 1}</label>
                <input
                  id={id}
                  className="control"
                  type="text"
                  autoComplete="off"
                  value={name}
                  aria-describedby="tournament-name-error"
                  onChange={(event) => {
                    const value = event.currentTarget.value;
                    setDrafts((current) =>
                      current.map((draft, draftIndex) => (draftIndex === index ? value : draft)),
                    );
                  }}
                />
              </div>
            );
          })}
        </div>
        <p id="tournament-name-error" className="tournament-error">
          {error}
        </p>
        <div className="tournament-actions">
          <button type="submit" className="control">
            Start tournament
          </button>
          <button type="button" className="control" onClick={leave}>
            Leave tournament
          </button>
        </div>
      </form>
    </section>
  );
}
