import { useRef, useState } from 'react';
import { createGame, isWon } from '../game.ts';
import { encodeTournamentJson, decodeTournamentJson } from './exchange.ts';
import type { TournamentDocumentRead } from './exchange.ts';
import { activateSession, initialSession, replaceGame } from '../session/session.ts';
import { useSessionClock } from '../session/use-session-clock.ts';
import { createTournamentDeals } from './deals.ts';
import {
  advanceTournament,
  createTournament,
  currentMatch,
  currentPlayer,
  nextTournamentAction,
  recordTournamentResult,
} from './rules.ts';
import {
  browserTournamentStore,
  prependFinishedTournament,
  readTournamentHistory,
  writeTournamentHistory,
} from './storage.ts';
import type { Session } from '../session/session.ts';
import type { Tournament } from './model.ts';

export function useTournament() {
  const [store] = useState(browserTournamentStore);
  const [loadedHistory] = useState(() => readTournamentHistory(store));
  const [history, setHistory] = useState(loadedHistory.tournaments);
  const [storageAvailable, setStorageAvailable] = useState(loadedHistory.available);
  const [tournament, setTournament] = useState<Tournament | null>(null);
  const tournamentRef = useRef(tournament);
  const [turnStarted, setTurnStarted] = useState(false);
  const [turnSession, setTurnSession] = useState(() =>
    initialSession('np1-4-1', { size: 4, bestMoves: {} }),
  );
  const current = useRef(turnSession);
  const [notice, setNotice] = useState('');
  const [announcement, setAnnouncement] = useState(0);

  function commitTournament(next: Tournament | null): void {
    tournamentRef.current = next;
    setTournament(next);
  }

  function commitSession(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setTurnSession(next);
  }

  const clock = useSessionClock(
    turnSession,
    current,
    commitSession,
    tournament !== null && tournament.status === 'active' && turnStarted,
  );

  function publish(message: string): void {
    setNotice(message);
    setAnnouncement((value) => value + 1);
  }

  function saveFinished(value: Tournament): void {
    const next = prependFinishedTournament(value, history);
    setHistory(next);
    setStorageAvailable(writeTournamentHistory(store, next));
  }

  function start(names: readonly string[], playerCount: 4 | 8): void {
    try {
      const codes = createTournamentDeals(playerCount, history);
      const next = createTournament(names, playerCount, codes);
      clock.reset();
      setTurnStarted(false);
      commitTournament(next);
      const player = currentPlayer(next);
      publish(player ? `Now playing: ${player.name}` : 'Tournament started.');
    } catch {
      publish('Could not create tournament deals.');
    }
  }

  function startTurn(): void {
    const event = tournamentRef.current;
    const match = event ? currentMatch(event) : null;
    const action = event ? nextTournamentAction(event) : null;
    if (!event || event.status !== 'active' || !match || action) return;
    clock.reset();
    commitSession(replaceGame(current.current, createGame(match.boardCode), false));
    setTurnStarted(true);
    const player = currentPlayer(event);
    publish(player ? `Now playing: ${player.name}` : '');
  }

  function advance(): void {
    const event = tournamentRef.current;
    if (!event) return;
    const action = nextTournamentAction(event);
    const next = advanceTournament(event);
    if (next === event) return;
    clock.reset();
    commitTournament(next);
    if (action === 'turn' || action === 'match') setTurnStarted(false);
    const player = currentPlayer(next);
    publish(player ? `Now playing: ${player.name}` : '');
  }

  function activate(index: number): void {
    clock.synchronize();
    const before = current.current;
    const nextSession = activateSession(before, index);
    commitSession(nextSession);
    if (nextSession.announcement !== before.announcement) setNotice('');
    if (nextSession === before || !isWon(nextSession.game) || isWon(before.game)) return;
    const event = tournamentRef.current;
    if (!event) return;
    const nextTournament = recordTournamentResult(event, {
      elapsedMs: nextSession.game.elapsedMs,
      moves: nextSession.game.moves,
    });
    if (nextTournament === event) return;
    commitTournament(nextTournament);
    if (nextTournament.status === 'finished') {
      saveFinished(nextTournament);
      publish(`Champion: ${nextTournament.champion?.name ?? ''}`);
    } else {
      publish(`${currentPlayer(event)?.name ?? 'Player'} finished their turn.`);
    }
  }

  function exportJson(): string {
    const currentTournament = tournamentRef.current;
    if (currentTournament && turnStarted) clock.synchronize();
    const event = currentTournament ?? history[0] ?? null;
    if (!event) {
      publish('No tournament is available to export.');
      return '';
    }
    const game = currentTournament && turnStarted ? current.current.game : null;
    publish('Tournament exported.');
    return encodeTournamentJson(event, game, Boolean(game));
  }

  function loadJson(text: string): boolean {
    const result: TournamentDocumentRead = decodeTournamentJson(text);
    if (!result.document) {
      publish(result.error ?? 'Invalid tournament JSON.');
      return false;
    }
    const { tournament: loaded, turnGame, turnStarted: hasTurnStarted } = result.document;
    const match = currentMatch(loaded);
    if (!match) {
      publish('Invalid tournament JSON.');
      return false;
    }
    clock.reset();
    commitTournament(loaded);
    setTurnStarted(hasTurnStarted);
    commitSession(replaceGame(current.current, turnGame ?? createGame(match.boardCode), false));
    if (loaded.status === 'finished') saveFinished(loaded);
    const player = currentPlayer(loaded);
    publish(
      loaded.champion
        ? `Champion: ${loaded.champion.name}`
        : player
          ? `Now playing: ${player.name}`
          : 'Tournament loaded.',
    );
    return true;
  }

  return {
    activate,
    advance,
    announcement: `${announcement}-${turnSession.announcement}`,
    exportJson,
    feedback: notice || (turnStarted ? turnSession.feedback : ''),
    history,
    loadJson,
    start,
    report: publish,
    startTurn,
    storageAvailable,
    tournament,
    turnGame: turnStarted ? turnSession.game : null,
    turnStarted,
    turnSession,
    activeMatch: tournament ? currentMatch(tournament) : null,
  };
}

import { ELAPSED_MAX_MS, isWon } from '../game.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { hasExactKeys, isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import { currentMatch } from './rules.ts';
import { decodeTournamentRecord } from './validate.ts';
import type { GameState } from '../game.ts';
import type {
  Tournament,
  TournamentMatch,
  TournamentPlayer,
  TournamentResult,
  TournamentRound,
} from './model.ts';

const TOURNAMENT_MAX_BYTES = 65_536;

interface TournamentDocument {
  readonly tournament: Tournament;
  readonly turnGame: GameState | null;
  readonly turnStarted: boolean;
}

export interface TournamentDocumentRead {
  readonly document: TournamentDocument | null;
  readonly error: string | null;
}

function playerData(player: TournamentPlayer | null): unknown {
  return player ? { name: player.name, seed: player.seed } : null;
}

function resultData(result: TournamentResult | null): unknown {
  return result ? { elapsedMs: result.elapsedMs, moves: result.moves } : null;
}

function matchData(match: TournamentMatch): unknown {
  return {
    boardCode: match.boardCode,
    id: match.id,
    players: [playerData(match.players[0]), playerData(match.players[1])],
    results: [resultData(match.results[0]), resultData(match.results[1])],
    winner: playerData(match.winner),
  };
}

function roundData(round: TournamentRound): unknown {
  return { matches: round.matches.map(matchData), name: round.name, size: round.size };
}

function tournamentRecordData(tournament: Tournament): unknown {
  return {
    champion: playerData(tournament.champion),
    id: tournament.id,
    matchIndex: tournament.matchIndex,
    playerCount: tournament.playerCount,
    playerIndex: tournament.playerIndex,
    players: tournament.players.map(playerData),
    roundIndex: tournament.roundIndex,
    rounds: tournament.rounds.map(roundData),
    status: tournament.status,
  };
}

export function encodeTournamentJson(
  tournament: Tournament,
  turnGame: GameState | null,
  turnStarted: boolean,
): string {
  return JSON.stringify(
    {
      format: 'neon-pairs/tournament',
      tournament: tournamentRecordData(tournament),
      turn: {
        elapsedMs: turnGame ? turnGame.elapsedMs : null,
        game: turnGame ? encodeSnapshot(turnGame) : null,
        started: turnStarted,
      },
      version: 1,
    },
    null,
    2,
  );
}

function object(value: unknown, keys: readonly string[]): Record<string, unknown> | null {
  if (!isJsonObject(value)) return null;
  for (const key of Object.keys(value))
    if (!keys.includes(key)) throw new Error(`Unknown field: ${key}.`);
  return hasExactKeys(value, keys) ? value : null;
}

export function decodeTournamentJson(text: string): TournamentDocumentRead {
  if (!isWithinBytes(text, TOURNAMENT_MAX_BYTES))
    return { document: null, error: 'Invalid tournament JSON.' };
  const parsed = parseJson(text);
  try {
    const root = object(parsed, ['format', 'tournament', 'turn', 'version']);
    if (!root || root.format !== 'neon-pairs/tournament' || root.version !== 1)
      return { document: null, error: 'Invalid tournament JSON.' };
    const record = decodeTournamentRecord(root.tournament);
    if (!record.tournament) return { document: null, error: record.error };
    const turn = object(root.turn, ['elapsedMs', 'game', 'started']);
    if (!turn || typeof turn.started !== 'boolean')
      return { document: null, error: 'Invalid tournament JSON.' };
    if (turn.game === null) {
      if (turn.elapsedMs !== null || turn.started)
        return { document: null, error: 'Invalid tournament JSON.' };
      return {
        document: { tournament: record.tournament, turnGame: null, turnStarted: false },
        error: null,
      };
    }
    if (typeof turn.game !== 'string' || typeof turn.elapsedMs !== 'number')
      return { document: null, error: 'Invalid tournament JSON.' };
    if (
      !turn.started ||
      !Number.isFinite(turn.elapsedMs) ||
      turn.elapsedMs < 0 ||
      turn.elapsedMs > ELAPSED_MAX_MS
    )
      return { document: null, error: 'Invalid tournament JSON.' };
    const game = decodeSnapshot(turn.game);
    const match = currentMatch(record.tournament);
    if (
      !game ||
      !match ||
      game.boardCode !== match.boardCode ||
      Math.floor(game.elapsedMs) !== Math.floor(turn.elapsedMs)
    )
      return { document: null, error: 'Invalid tournament JSON.' };
    const turnResult = match.results[record.tournament.playerIndex];
    if (isWon(game)) {
      if (!turnResult || turnResult.moves !== game.moves || turnResult.elapsedMs !== turn.elapsedMs)
        return { document: null, error: 'Invalid tournament JSON.' };
    } else if (turnResult) return { document: null, error: 'Invalid tournament JSON.' };
    return {
      document: {
        tournament: record.tournament,
        turnGame: { ...game, elapsedMs: turn.elapsedMs },
        turnStarted: true,
      },
      error: null,
    };
  } catch (error) {
    return {
      document: null,
      error: error instanceof Error ? error.message : 'Invalid tournament JSON.',
    };
  }
}

import { openingSeedPairs } from './layout.ts';
import type { Tournament, TournamentPlayer } from './model.ts';

function invalid(): never {
  throw new Error('Invalid tournament JSON.');
}

function samePlayer(first: TournamentPlayer | null, second: TournamentPlayer | null): boolean {
  return first?.name === second?.name && first?.seed === second?.seed;
}

export function validateTournamentBracket(tournament: Tournament): void {
  const { rounds } = tournament;
  const usedCodes = new Set<string>();
  for (let roundIndex = 0; roundIndex < rounds.length; roundIndex += 1) {
    const round = rounds[roundIndex];
    if (!round) return invalid();
    for (let matchIndex = 0; matchIndex < round.matches.length; matchIndex += 1) {
      const match = round.matches[matchIndex];
      if (!match || usedCodes.has(match.boardCode)) return invalid();
      usedCodes.add(match.boardCode);
      const expectedPlayers = expectedMatchPlayers(tournament, roundIndex, matchIndex);
      if (
        !samePlayer(match.players[0], expectedPlayers[0]) ||
        !samePlayer(match.players[1], expectedPlayers[1])
      )
        return invalid();
      const current = roundIndex === tournament.roundIndex && matchIndex === tournament.matchIndex;
      const earlier =
        roundIndex < tournament.roundIndex ||
        (roundIndex === tournament.roundIndex && matchIndex < tournament.matchIndex);
      if (earlier || (current && tournament.status === 'finished')) {
        if (!match.winner) return invalid();
      } else if (!current && match.winner) return invalid();
      if (!current && !match.winner && match.results.some(Boolean)) return invalid();
    }
  }
  const firstCode = rounds[0]?.matches[0]?.boardCode;
  if (tournament.id !== firstCode) return invalid();
  const currentRound = rounds[tournament.roundIndex];
  const current = currentRound?.matches[tournament.matchIndex];
  if (!current) return invalid();
  if (tournament.status === 'active') {
    if (tournament.champion) return invalid();
    if (tournament.playerIndex === 1 && !current.results[0]) return invalid();
    if (tournament.playerIndex === 0 && current.results[1]) return invalid();
    if (current.winner && tournament.playerIndex !== 1) return invalid();
    if (
      current.winner &&
      tournament.roundIndex === rounds.length - 1 &&
      tournament.matchIndex === (currentRound?.matches.length ?? 0) - 1
    )
      return invalid();
  } else {
    const lastRound = rounds.length - 1;
    const finalMatch = rounds[lastRound]?.matches.at(-1);
    if (
      tournament.roundIndex !== lastRound ||
      tournament.matchIndex !== (currentRound?.matches.length ?? 0) - 1 ||
      tournament.playerIndex !== 1 ||
      !finalMatch?.winner ||
      !samePlayer(tournament.champion, finalMatch.winner) ||
      rounds.some((round) => round.matches.some((match) => !match.winner))
    )
      return invalid();
  }
}

function expectedMatchPlayers(
  tournament: Tournament,
  roundIndex: number,
  matchIndex: number,
): readonly [TournamentPlayer | null, TournamentPlayer | null] {
  if (roundIndex === 0) {
    const pair = openingSeedPairs(tournament.playerCount)[matchIndex];
    if (!pair) return [null, null];
    return [tournament.players[pair[0]] ?? null, tournament.players[pair[1]] ?? null];
  }
  if (roundIndex > tournament.roundIndex) return [null, null];
  const previous = tournament.rounds[roundIndex - 1];
  return [
    previous?.matches[matchIndex * 2]?.winner ?? null,
    previous?.matches[matchIndex * 2 + 1]?.winner ?? null,
  ];
}

import { parseBoardCode } from '../deck.ts';
import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { normalizePlayerName } from './names.ts';
import { roundDefinitions } from './layout.ts';
import { winnerForMatch } from './rules.ts';
import { validateTournamentBracket } from './validate-bracket.ts';
import type {
  RoundName,
  Tournament,
  TournamentMatch,
  TournamentPlayer,
  TournamentResult,
  TournamentRound,
  TournamentStatus,
} from './model.ts';

export interface TournamentReadResult {
  readonly error: string | null;
  readonly tournament: Tournament | null;
}

function invalid(message = 'Invalid tournament JSON.'): never {
  throw new Error(message);
}

function object(value: unknown, keys: readonly string[]): Record<string, unknown> {
  if (!isJsonObject(value)) return invalid();
  for (const key of Object.keys(value))
    if (!keys.includes(key)) return invalid(`Unknown field: ${key}.`);
  if (!hasExactKeys(value, keys)) return invalid();
  return value;
}

function readPlayer(value: unknown): TournamentPlayer | null {
  if (value === null) return null;
  const player = object(value, ['name', 'seed']);
  if (typeof player.name !== 'string' || !isNonnegativeSafeInteger(player.seed)) return invalid();
  const name = normalizePlayerName(player.name);
  if (name !== player.name || Array.from(name).length < 2 || Array.from(name).length > 20)
    return invalid();
  return { name, seed: player.seed };
}

function readPlayerPair(
  value: unknown,
): readonly [TournamentPlayer | null, TournamentPlayer | null] {
  if (!Array.isArray(value) || value.length !== 2) return invalid();
  return [readPlayer(value[0]), readPlayer(value[1])];
}

function readResult(value: unknown): TournamentResult | null {
  if (value === null) return null;
  const result = object(value, ['elapsedMs', 'moves']);
  if (!isNonnegativeSafeInteger(result.moves) || typeof result.elapsedMs !== 'number')
    return invalid();
  if (
    !Number.isFinite(result.elapsedMs) ||
    result.elapsedMs < 0 ||
    result.elapsedMs > ELAPSED_MAX_MS
  )
    return invalid();
  return { elapsedMs: result.elapsedMs, moves: result.moves };
}

function readResultPair(
  value: unknown,
): readonly [TournamentResult | null, TournamentResult | null] {
  if (!Array.isArray(value) || value.length !== 2) return invalid();
  return [readResult(value[0]), readResult(value[1])];
}

function samePlayer(first: TournamentPlayer | null, second: TournamentPlayer | null): boolean {
  return first?.name === second?.name && first?.seed === second?.seed;
}

function readMatch(value: unknown, name: RoundName, size: number, index: number): TournamentMatch {
  const match = object(value, ['boardCode', 'id', 'players', 'results', 'winner']);
  if (typeof match.boardCode !== 'string' || typeof match.id !== 'string') return invalid();
  const parsedCode = parseBoardCode(match.boardCode);
  const prefix = name === 'Quarterfinal' ? 'QF' : name === 'Semifinal' ? 'SF' : 'F';
  if (!parsedCode || parsedCode.size !== size || match.id !== `${prefix}${index + 1}`)
    return invalid();
  const players = readPlayerPair(match.players);
  const results = readResultPair(match.results);
  const winner = readPlayer(match.winner);
  if (players.some((player, playerIndex) => !player && results[playerIndex])) return invalid();
  for (const result of results)
    if (result && (result.moves < size ** 2 / 2 || result.moves > MOVES_MAX)) return invalid();
  const expectedWinner = winnerForMatch(players, results);
  if (!samePlayer(winner, expectedWinner)) return invalid();
  return { boardCode: match.boardCode, id: match.id, players, results, winner };
}

function readRound(value: unknown, name: RoundName, size: number, count: number): TournamentRound {
  const round = object(value, ['matches', 'name', 'size']);
  if (round.name !== name || round.size !== size || !Array.isArray(round.matches)) return invalid();
  if (round.matches.length !== count) return invalid();
  return {
    matches: round.matches.map((match, index) => readMatch(match, name, size, index)),
    name,
    size,
  };
}

function readTournament(value: unknown): Tournament {
  const record = object(value, [
    'champion',
    'id',
    'matchIndex',
    'playerCount',
    'playerIndex',
    'players',
    'roundIndex',
    'rounds',
    'status',
  ]);
  const playerCountValue = record.playerCount;
  if (playerCountValue !== 4 && playerCountValue !== 8) return invalid();
  const playerCount = playerCountValue;
  if (typeof record.id !== 'string' || !Array.isArray(record.players)) return invalid();
  const roundIndex = record.roundIndex;
  const matchIndex = record.matchIndex;
  const playerIndex = record.playerIndex;
  const statusValue = record.status;
  if (!isNonnegativeSafeInteger(roundIndex) || !isNonnegativeSafeInteger(matchIndex))
    return invalid();
  if (playerIndex !== 0 && playerIndex !== 1) return invalid();
  if (statusValue !== 'active' && statusValue !== 'finished') return invalid();
  const status: TournamentStatus = statusValue;
  if (!Array.isArray(record.rounds)) return invalid();
  const players = record.players.map(readPlayer);
  if (players.length !== playerCount || players.some((player) => !player)) return invalid();
  const entrants = players.filter((player): player is TournamentPlayer => player !== null);
  if (entrants.some((player, index) => player.seed !== index + 1)) return invalid();
  if (new Set(entrants.map((player) => player.name.toLowerCase())).size !== playerCount)
    return invalid();
  const definitions = roundDefinitions(playerCount);
  if (record.rounds.length !== definitions.length) return invalid();
  const rounds = definitions.map((definition, index) =>
    readRound(record.rounds[index], definition.name, definition.size, definition.count),
  );
  const tournament: Tournament = {
    champion: readPlayer(record.champion),
    id: record.id,
    matchIndex,
    playerCount,
    playerIndex,
    players: entrants,
    roundIndex,
    rounds,
    status,
  };
  validateTournamentBracket(tournament);
  return tournament;
}

export function decodeTournamentRecord(value: unknown): TournamentReadResult {
  try {
    return { error: null, tournament: readTournament(value) };
  } catch (error) {
    return {
      error: error instanceof Error ? error.message : 'Invalid tournament JSON.',
      tournament: null,
    };
  }
}

import type {
  Tournament,
  TournamentAction,
  TournamentMatch,
  TournamentPlayer,
  TournamentResult,
} from './model.ts';
import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';

export function currentMatch(tournament: Tournament): TournamentMatch | null {
  return tournament.rounds[tournament.roundIndex]?.matches[tournament.matchIndex] ?? null;
}

export function currentPlayer(tournament: Tournament): TournamentPlayer | null {
  return currentMatch(tournament)?.players[tournament.playerIndex] ?? null;
}

export function winnerForMatch(
  players: readonly [TournamentPlayer | null, TournamentPlayer | null],
  results: readonly [TournamentResult | null, TournamentResult | null],
): TournamentPlayer | null {
  const first = players[0];
  const second = players[1];
  const firstResult = results[0];
  const secondResult = results[1];
  if (!first || !second || !firstResult || !secondResult) return null;
  if (firstResult.moves !== secondResult.moves)
    return firstResult.moves < secondResult.moves ? first : second;
  if (firstResult.elapsedMs !== secondResult.elapsedMs)
    return firstResult.elapsedMs < secondResult.elapsedMs ? first : second;
  return first.seed < second.seed ? first : second;
}

export function nextTournamentAction(tournament: Tournament): TournamentAction {
  if (tournament.status !== 'active') return null;
  const match = currentMatch(tournament);
  if (!match) return null;
  if (tournament.playerIndex === 0 && match.results[0] && !match.results[1]) return 'turn';
  return match.winner ? 'match' : null;
}

export function recordTournamentResult(
  tournament: Tournament,
  result: TournamentResult,
): Tournament {
  if (
    tournament.status !== 'active' ||
    !Number.isSafeInteger(result.moves) ||
    result.moves < 0 ||
    result.moves > MOVES_MAX
  )
    return tournament;
  if (
    !Number.isFinite(result.elapsedMs) ||
    result.elapsedMs < 0 ||
    result.elapsedMs > ELAPSED_MAX_MS
  )
    return tournament;
  const match = currentMatch(tournament);
  if (!match || !match.players[tournament.playerIndex] || match.results[tournament.playerIndex])
    return tournament;
  const results: readonly [TournamentResult | null, TournamentResult | null] =
    tournament.playerIndex === 0 ? [result, match.results[1]] : [match.results[0], result];
  const winner = winnerForMatch(match.players, results);
  const nextMatch = { ...match, results, winner };
  const nextRounds = tournament.rounds.map((round, index) =>
    index !== tournament.roundIndex
      ? round
      : {
          ...round,
          matches: round.matches.map((entry, matchIndex) =>
            matchIndex === tournament.matchIndex ? nextMatch : entry,
          ),
        },
  );
  const finalRound = tournament.roundIndex === tournament.rounds.length - 1;
  const finalMatch =
    tournament.matchIndex === (tournament.rounds[tournament.roundIndex]?.matches.length ?? 0) - 1;
  const finished = Boolean(winner && finalRound && finalMatch);
  return {
    ...tournament,
    champion: finished ? winner : null,
    rounds: nextRounds,
    status: finished ? 'finished' : 'active',
  };
}

export function advanceTournament(tournament: Tournament): Tournament {
  const action = nextTournamentAction(tournament);
  if (action === 'turn') return { ...tournament, playerIndex: 1 };
  if (action !== 'match') return tournament;
  const round = tournament.rounds[tournament.roundIndex];
  if (!round) return tournament;
  if (tournament.matchIndex + 1 < round.matches.length)
    return { ...tournament, matchIndex: tournament.matchIndex + 1, playerIndex: 0 };
  const nextRound = tournament.rounds[tournament.roundIndex + 1];
  if (!nextRound) return tournament;
  const matches = nextRound.matches.map((match, index) => {
    const first = round.matches[index * 2]?.winner ?? null;
    const second = round.matches[index * 2 + 1]?.winner ?? null;
    return { ...match, players: [first, second] as const };
  });
  const rounds = tournament.rounds.map((entry, index) =>
    index === tournament.roundIndex + 1 ? { ...entry, matches } : entry,
  );
  return {
    ...tournament,
    matchIndex: 0,
    playerIndex: 0,
    roundIndex: tournament.roundIndex + 1,
    rounds,
  };
}

import { hasExactKeys, isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import { decodeTournamentRecord } from './validate.ts';
import type { TournamentReadResult } from './validate.ts';
import type { Tournament } from './model.ts';

const TOURNAMENTS_KEY = 'np3:tournaments';
const TOURNAMENTS_VERSION = 3;
const TOURNAMENTS_LIMIT = 10;

interface TournamentStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

interface TournamentHistoryRead {
  readonly available: boolean;
  readonly tournaments: readonly Tournament[];
}

export function prependFinishedTournament(
  tournament: Tournament,
  history: readonly Tournament[],
): readonly Tournament[] {
  return [tournament, ...history.filter((item) => item.id !== tournament.id)].slice(
    0,
    TOURNAMENTS_LIMIT,
  );
}

export function browserTournamentStore(): TournamentStore | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

export function readTournamentHistory(store: TournamentStore | null): TournamentHistoryRead {
  if (!store) return { available: false, tournaments: [] };
  let text: string | null;
  try {
    text = store.getItem(TOURNAMENTS_KEY);
  } catch {
    return { available: false, tournaments: [] };
  }
  if (!text) return { available: true, tournaments: [] };
  if (!isWithinBytes(text, 65_536)) return { available: true, tournaments: [] };
  const value = parseJson(text);
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['items', 'v']) ||
    value.v !== TOURNAMENTS_VERSION ||
    !Array.isArray(value.items) ||
    value.items.length > TOURNAMENTS_LIMIT
  )
    return { available: true, tournaments: [] };
  const tournaments: Tournament[] = [];
  for (const item of value.items) {
    const result: TournamentReadResult = decodeTournamentRecord(item);
    if (!result.tournament || result.tournament.status !== 'finished')
      return { available: true, tournaments: [] };
    tournaments.push(result.tournament);
  }
  return { available: true, tournaments };
}

export function writeTournamentHistory(
  store: TournamentStore | null,
  tournaments: readonly Tournament[],
): boolean {
  if (!store) return false;
  try {
    store.setItem(
      TOURNAMENTS_KEY,
      JSON.stringify({ items: tournaments.slice(0, TOURNAMENTS_LIMIT), v: TOURNAMENTS_VERSION }),
    );
    return true;
  } catch {
    return false;
  }
}

import { useRef, useState } from 'react';
import { createGame } from '../game.ts';
import { parseBoardCode, isValidSize } from '../deck.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { freshBoardCode } from './fresh-board.ts';
import { activateSession, initialSession, replaceGame, SessionNotice } from './session.ts';
import { readPreferences } from './storage.ts';
import { browserStore, useSavedPreferences } from './use-saved-preferences.ts';
import { useSessionClock } from './use-session-clock.ts';
import type { Session } from './session.ts';

export function useGame(clockEnabled = true) {
  const [store] = useState(browserStore);
  const [session, setSession] = useState(() => {
    const preferences = readPreferences(store);
    return initialSession(freshBoardCode(preferences.size), preferences);
  });
  const current = useRef(session);

  function commit(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useSessionClock(session, current, commit, clockEnabled);
  useSavedPreferences(store, session.preferences);

  function newGame(size = current.current.game.size): void {
    if (!isValidSize(size)) return;
    const next = createGame(freshBoardCode(size, current.current.game.seed));
    clock.reset();
    commit(replaceGame(current.current, next, false));
  }

  function restart(): void {
    clock.reset();
    commit(replaceGame(current.current, createGame(current.current.game.boardCode), false));
  }

  function notice(feedback: string): void {
    commit({
      ...current.current,
      feedback,
      loadNotice: feedback,
      announcement: current.current.announcement + 1,
    });
  }

  function loadBoard(code: string): boolean {
    code = code.trim();
    if (!parseBoardCode(code)) {
      notice(SessionNotice.invalidBoard);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false));
    return true;
  }

  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) {
      notice(SessionNotice.invalidSnapshot);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, game, true));
    return true;
  }

  function exportSnapshot(): string {
    // Rendered state can trail the active clock by a tick.
    clock.synchronize();
    return encodeSnapshot(current.current.game);
  }

  function activate(index: number): void {
    clock.synchronize();
    commit(activateSession(current.current, index));
  }

  function resume(): void {
    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  return {
    session,
    newGame,
    restart,
    loadBoard,
    loadSnapshot,
    exportSnapshot,
    activate,
    resume,
    synchronizeClock: clock.synchronize,
    resetClock: clock.reset,
  };
}

import { useEffect, useRef, useState } from 'react';
import { Board } from './board/Board.tsx';
