        </>
      ) : (
        <TournamentScreen
          onBack={() => {
            controller.resetClock();
            setScreen('game');
          }}
        />
      )}
    </main>
  );
}

import { useEffect, useRef } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from './browser-clock.ts';
import { tickSession } from './session.ts';
import type { RefObject } from 'react';
import type { Session } from './session.ts';

export function useSessionClock(
  session: Session,
  current: RefObject<Session>,
  commit: (next: Session) => void,
  enabled = true,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const won = isWon(session.game);

  function running(): boolean {
    return (
      visible.current &&
      enabled &&
      !current.current.paused &&
      current.current.game.started &&
      !isWon(current.current.game)
    );
  }

  function synchronize(generation = current.current.generation): void {
    if (generation !== current.current.generation) return;
    const now = performance.now();
    const step = elapsedStep(clock.current, now, running());
    clock.current = step.clock;
    if (step.milliseconds) commit(tickSession(current.current, generation, step.milliseconds));
  }

  useEffect(() => {
    const generation = session.generation;
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      if (!active || generation !== current.current.generation || !running()) return;
      const selection = current.current.game.selection;
      const delay =
        selection.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize(generation);
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active || generation !== current.current.generation) return;
      synchronize(generation);
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [enabled, session.generation, session.game.started, session.paused, won]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
      visible.current = !document.hidden;
    },
  };
}

import { useEffect, useRef } from 'react';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { GameStatus } from '../status/GameStatus.tsx';
import { TournamentLeave } from './TournamentLeave.tsx';
import { nextTournamentAction } from './rules.ts';
import type { GameState } from '../game.ts';
import type { Session } from '../session/session.ts';
import type { Tournament, TournamentMatch } from './model.ts';

interface TournamentPlayProps {
  activate(index: number): void;
  advance(): void;
  back(): void;
  leave(): void;
  match: TournamentMatch | null;
  startTurn(): void;
  tournament: Tournament;
  turnGame: GameState | null;
  turnSession: Session;
  turnStarted: boolean;
}

export function TournamentPlay({
  activate,
  advance,
  back,
  leave,
  match,
  startTurn,
  tournament,
  turnGame,
  turnSession,
  turnStarted,
}: TournamentPlayProps) {
  const board = useRef<BoardFocus>(null);
  const startButton = useRef<HTMLButtonElement>(null);
  const championHeading = useRef<HTMLHeadingElement>(null);
  const action = nextTournamentAction(tournament);
  const player = match?.players[tournament.playerIndex] ?? null;
  const round = tournament.rounds[tournament.roundIndex];

  useEffect(() => {
    if (tournament.status === 'finished') championHeading.current?.focus();
    else if (turnStarted) board.current?.focusRemembered();
    else startButton.current?.focus();
  }, [
    tournament.status,
    tournament.roundIndex,
    tournament.matchIndex,
    tournament.playerIndex,
    turnStarted,
  ]);

  if (tournament.status === 'finished') {
    return (
      <section className="tournament-play" aria-labelledby="champion-heading">
        <h3 id="champion-heading" ref={championHeading} tabIndex={-1}>
          Champion: {tournament.champion?.name ?? ''}
        </h3>
        <div className="tournament-actions">
          <button type="button" className="control" onClick={back}>
            Back to game
          </button>
        </div>
      </section>
    );
  }

  return (
    <section className="tournament-play" aria-labelledby="tournament-round-heading">
      <h3 id="tournament-round-heading">Round: {round?.name ?? ''}</h3>
      <p className="tournament-match-label">Match: {match?.id ?? ''}</p>
      <p className="tournament-now-playing">Now playing: {player?.name ?? ''}</p>
      {match && <p className="tournament-deal">Board code: {match.boardCode}</p>}
      <div className="tournament-actions">
        {action === 'turn' ? (
          <button type="button" className="control" onClick={advance}>
            Next turn
          </button>
        ) : action === 'match' ? (
          <button type="button" className="control" onClick={advance}>
            Next match
          </button>
        ) : !turnStarted ? (
          <button ref={startButton} type="button" className="control" onClick={startTurn}>
            Start turn
          </button>
        ) : null}
        <TournamentLeave onLeave={leave} />
      </div>
      {turnStarted && turnGame && (
        <div className="tournament-game">
          <GameStatus
            game={turnGame}
            best={undefined}
            celebration={turnSession.celebration}
            showBest={false}
          />
          <p id="board-help" className="help">
            Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
            reveals a card.
          </p>
          <Board key={turnSession.generation} game={turnGame} activate={activate} ref={board} />
        </div>
      )}
    </section>
  );
}

import { useState } from 'react';
import type { FormEvent } from 'react';
import { checkPlayerNames } from './names.ts';

interface TournamentSetupProps {
  start(names: readonly string[], count: 4 | 8): void;
  leave(): void;
  report(message: string): void;
}

export function TournamentSetup({ start, leave, report }: TournamentSetupProps) {
  const [count, setCount] = useState<4 | 8>(4);
  const [drafts, setDrafts] = useState(() => Array.from({ length: 8 }, () => ''));
  const [error, setError] = useState('');

  function submit(event: FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    const checked = checkPlayerNames(drafts, count);
    if (!checked.accepted) {
      setError(checked.message);
      report(checked.message);
      return;
    }
    setError('');
    start(checked.names, count);
  }

  return (
    <section className="tournament-setup" aria-labelledby="tournament-setup-title">
      <h3 id="tournament-setup-title">Set up a tournament</h3>
      <form onSubmit={submit}>
        <div className="tournament-count">
          <label htmlFor="tournament-player-count">Players</label>
          <select
            id="tournament-player-count"
            className="control"
            value={count}
            onChange={(event) => setCount(event.currentTarget.value === '8' ? 8 : 4)}
          >
            <option value={4}>4</option>
            <option value={8}>8</option>
          </select>
        </div>
        <div className="tournament-name-grid">
          {drafts.slice(0, count).map((name, index) => {
            const id = `tournament-player-${index + 1}`;
            return (
              <div className="tournament-name-field" key={id}>
                <label htmlFor={id}>Player {index + 1}</label>
                <input
                  id={id}
                  className="control"
                  type="text"
                  autoComplete="off"
                  value={name}
                  aria-describedby="tournament-name-error"
                  onChange={(event) => {
                    const value = event.currentTarget.value;
                    setDrafts((current) =>
                      current.map((draft, draftIndex) => (draftIndex === index ? value : draft)),
                    );
                  }}
                />
              </div>
            );
          })}
        </div>
        <p id="tournament-name-error" className="tournament-error">
          {error}
        </p>
        <div className="tournament-actions">
          <button type="submit" className="control">
            Start tournament
          </button>
          <button type="button" className="control" onClick={leave}>
            Leave tournament
          </button>
        </div>
      </form>
    </section>
  );
}

