  storageAvailable: boolean;
}) {
  return (
    <section className="past-tournaments" aria-labelledby="past-tournaments-title">
      <h3 id="past-tournaments-title">Past tournaments</h3>
      {!storageAvailable && (
        <p className="storage-warning">Progress won't be saved on this device.</p>
      )}
      {tournaments.length === 0 ? (
        <p>No finished tournaments yet.</p>
      ) : (
        <div className="tournament-table-scroll">
          <table>
            <caption>Past tournaments</caption>
            <thead>
              <tr>
                <th scope="col">Players</th>
                <th scope="col">Champion</th>
                <th scope="col">Match results</th>
              </tr>
            </thead>
            <tbody>
              {tournaments.map((tournament) => (
                <tr key={tournament.id}>
                  <td>{tournament.players.map((player) => player.name).join(', ')}</td>
                  <td>{tournament.champion?.name ?? '—'}</td>
                  <td>{summary(tournament)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

import { useEffect, useRef, useState } from 'react';

export function TournamentLeave({ onLeave }: { onLeave(): void }) {
  const [confirming, setConfirming] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const dialog = useRef<HTMLDialogElement>(null);
  const keepPlaying = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!confirming || !dialog.current || dialog.current.open) return;
    dialog.current.showModal();
    keepPlaying.current?.focus();
  }, [confirming]);

  function stay(): void {
    dialog.current?.close();
    setConfirming(false);
    trigger.current?.focus();
  }

  function leave(): void {
    dialog.current?.close();
    setConfirming(false);
    onLeave();
  }

  return (
    <>
      <button ref={trigger} type="button" className="control" onClick={() => setConfirming(true)}>
        Leave tournament
      </button>
      <dialog
        ref={dialog}
        className="tournament-confirmation"
        aria-labelledby="leave-tournament-title"
        aria-describedby="leave-tournament-description"
        onCancel={(event) => {
          event.preventDefault();
          stay();
        }}
      >
        <h3 id="leave-tournament-title">Leave this tournament?</h3>
        <p id="leave-tournament-description">
          Leaving stops the tournament. This unfinished tournament won't be added to Past
          tournaments.
        </p>
        <div className="tournament-actions">
          <button ref={keepPlaying} type="button" className="control" onClick={stay}>
            Keep playing
          </button>
          <button type="button" className="control" onClick={leave}>
            Leave
          </button>
        </div>
      </dialog>
    </>
  );
}

import { parseBoardCode } from '../deck.ts';
import type { RoundDefinition, Tournament, TournamentPlayer } from './model.ts';

export function roundDefinitions(playerCount: 4 | 8): readonly RoundDefinition[] {
  return playerCount === 4
    ? [
        { name: 'Semifinal', size: 6, count: 2 },
        { name: 'Final', size: 8, count: 1 },
      ]
    : [
        { name: 'Quarterfinal', size: 4, count: 4 },
        { name: 'Semifinal', size: 6, count: 2 },
        { name: 'Final', size: 8, count: 1 },
      ];
}

export function openingSeedPairs(playerCount: 4 | 8): readonly (readonly [number, number])[] {
  return playerCount === 4
    ? [
        [0, 3],
        [1, 2],
      ]
    : [
        [0, 7],
        [3, 4],
        [2, 5],
        [1, 6],
      ];
}

export function plannedMatchSizes(playerCount: 4 | 8): readonly number[] {
  return roundDefinitions(playerCount).flatMap(({ count, size }) =>
    Array.from({ length: count }, () => size),
  );
}

export function createTournament(
  names: readonly string[],
  playerCount: 4 | 8,
  codes: readonly string[],
): Tournament {
  if (names.length !== playerCount || codes.length !== plannedMatchSizes(playerCount).length)
    throw new Error('Tournament setup is incomplete.');
  const players = names.map((name, index) => ({ name, seed: index + 1 }));
  const sizes = plannedMatchSizes(playerCount);
  if (new Set(codes).size !== codes.length) throw new Error('Tournament deals must be unique.');
  for (let index = 0; index < codes.length; index += 1) {
    const parsed = parseBoardCode(codes[index] ?? '');
    if (!parsed || parsed.size !== sizes[index])
      throw new Error('Tournament deal has the wrong size.');
  }
  let codeIndex = 0;
  const rounds = roundDefinitions(playerCount).map((definition, roundIndex) => {
    const matches = Array.from({ length: definition.count }, (_, matchIndex) => {
      const boardCode = codes[codeIndex];
      codeIndex += 1;
      const prefix =
        definition.name === 'Quarterfinal' ? 'QF' : definition.name === 'Semifinal' ? 'SF' : 'F';
      const playersInMatch: readonly [TournamentPlayer | null, TournamentPlayer | null] =
        roundIndex === 0 ? openingPlayerPair(players, playerCount, matchIndex) : [null, null];
      if (!boardCode) throw new Error('Tournament deal is missing.');
      return {
        boardCode,
        id: `${prefix}${matchIndex + 1}`,
        players: playersInMatch,
        results: [null, null] as const,
        winner: null,
      };
    });
    return { matches, name: definition.name, size: definition.size };
  });
  const firstCode = rounds[0]?.matches[0]?.boardCode;
  if (!firstCode) throw new Error('Tournament has no opening match.');
  return {
    champion: null,
    id: firstCode,
    matchIndex: 0,
    playerCount,
    playerIndex: 0,
    players,
    roundIndex: 0,
    rounds,
    status: 'active',
  };
}

function openingPlayerPair(
  players: readonly TournamentPlayer[],
  playerCount: 4 | 8,
  matchIndex: number,
): readonly [TournamentPlayer | null, TournamentPlayer | null] {
  const pair = openingSeedPairs(playerCount)[matchIndex];
  if (!pair) throw new Error('Tournament pairing is missing.');
  return [players[pair[0]] ?? null, players[pair[1]] ?? null];
}

import { freshBoardCode } from '../session/fresh-board.ts';
import { plannedMatchSizes } from './layout.ts';
import type { Tournament } from './model.ts';

export function createTournamentDeals(
  playerCount: 4 | 8,
  history: readonly Tournament[],
): string[] {
  const used = new Set(
    history.flatMap((item) =>
      item.rounds.flatMap((round) => round.matches.map((match) => match.boardCode)),
    ),
  );
  return plannedMatchSizes(playerCount).map((size) => {
    let code = freshBoardCode(size);
    while (used.has(code)) code = freshBoardCode(size);
    used.add(code);
    return code;
  });
}

